/**
 * LUC Credit Exchange Rate Configuration
 * 
 * Strategy: 1 LUC = 10 Naira (₦)
 * This creates a high perceived value for students while remaining
 * sustainable for the platform.
 */

export const LUC_EXCHANGE_RATE = 10; // 1 LUC = 10 ₦

/**
 * Converts LUC Credits to Naira
 * @param {number} luc - The amount in LUC Credits
 * @returns {number} - The equivalent amount in Naira
 */
export const lucToNaira = (luc) => {
    return luc * LUC_EXCHANGE_RATE;
};

/**
 * Converts Naira to LUC Credits (for buying credits)
 * @param {number} naira - The amount in Naira
 * @returns {number} - The equivalent amount in LUC Credits
 */
export const nairaToLuc = (naira) => {
    return Math.floor(naira / LUC_EXCHANGE_RATE);
};

/**
 * Formats a LUC amount with the currency symbol
 * @param {number} amount - The numeric amount
 * @returns {string} - Formatted string (e.g. "500 LUC")
 */
export const formatLuc = (amount) => {
    return `${new Intl.NumberFormat().format(amount)} LUC`;
};

/**
 * Formats a Naira amount with the currency symbol
 * @param {number} amount - The numeric amount
 * @returns {string} - Formatted string (e.g. "₦5,000")
 */
export const formatNaira = (amount) => {
    return `₦${new Intl.NumberFormat().format(amount)}`;
};
